from full_a import cat, C

cat("heroes", "Judges & Heroes", "Unlikely heroes from Israel’s wild early days.", "gideon", [
 dict(id="deborah", name="Deborah", role="Prophet and judge who led Israel to victory", art=None,
  facts=["Israel’s only female judge", "Held court under a palm tree", "Led an army"], cards=[
  C("Judge under the palm", "Deborah was a prophet and Israel’s leader. People came to her under a palm tree to settle disputes.",
    "For 20 years the Canaanite king Jabin and his general Sisera, with 900 iron chariots, had cruelly oppressed Israel. The people cried out to God.", ("Judges",4)),
  C("“Has not the Lord commanded you?”", "Deborah summoned Barak to lead 10,000 men. He’d only go if she came. She went — and said a woman would get the glory.",
    "She told him the honor of defeating Sisera would go to a woman instead.", ("Judges",4)),
  C("Victory", "Israel charged down Mount Tabor. God threw Sisera’s army into confusion, and a woman named Jael killed Sisera in her tent.",
    "Deborah’s song in Judges 5 says the stars fought from heaven and the river Kishon swept the enemy away — likely a storm that bogged down the chariots. The land had peace for 40 years.", ("Judges",5)),
 ]),
 dict(id="gideon", name="Gideon", role="The scared farmer God called a mighty warrior", art="gideon",
  facts=["Hid from enemies", "Asked for signs with a fleece", "Won with 300 men"], cards=[
  C("“Mighty warrior”", "Gideon was threshing wheat in a winepress to hide it from Midianite raiders when an angel greeted him: “The Lord is with you, mighty warrior.”",
    "Gideon answered, “If the Lord is with us, why has all this happened?” He said his clan was the weakest and he was the least in his family.", ("Judges",6)),
  C("Tearing down Baal", "God’s first command: tear down his father’s altar to Baal. Gideon did it — at night, because he was afraid.",
    "The town wanted to kill him. His father said, “If Baal really is a god, he can defend himself.”", ("Judges",6)),
  C("The fleece", "Gideon asked God for proof: make a wool fleece wet and the ground dry — then the reverse. God did both.",
    "God was patient with his fear.", ("Judges",6)),
  C("From 32,000 to 300", "God said Gideon’s army was too big. Fearful men went home, then God kept only the 300 who lapped water from their hands.",
    "“In order that Israel may not boast against Me that her own strength has saved her.”", ("Judges",7)),
  C("Jars and torches", "At night, the 300 surrounded the camp, smashed jars, raised torches, blew trumpets and shouted, “A sword for the Lord and for Gideon!”",
    "The Midianites panicked and turned their swords on each other. Later Gideon refused to be king — but made a gold ephod that became an idol for Israel.", ("Judges",7)),
 ]),
 dict(id="samson", name="Samson", role="The strongman with a weakness", art="samson-death",
  facts=["Never cut his hair", "Killed a lion barehanded", "Betrayed by Delilah"], cards=[
  C("Set apart", "An angel told a childless couple their son would be a Nazirite from birth — no razor on his head — and would begin to rescue Israel from the Philistines.",
    "Nazirites didn’t cut their hair, drink wine or touch dead bodies. Samson broke every part of the vow except his hair.", ("Judges",13)),
  C("The lion and the riddle", "Samson tore apart a lion barehanded, later found bees and honey in its body, and made a riddle out of it at his wedding.",
    "His Philistine wedding guests pressured his bride to get the answer, and he killed thirty Philistines to pay the bet. A cycle of revenge began.", ("Judges",14)),
  C("Super strength", "He killed a thousand Philistines with a donkey’s jawbone and carried Gaza’s city gates up a hill.",
    "He judged Israel for 20 years.", ("Judges",15)),
  C("Delilah", "The Philistines paid Delilah 1,100 silver pieces each to learn his secret. Three times he lied. The fourth, he told her.",
    "She lulled him to sleep on her lap and had his seven braids shaved. “The Philistines are upon you, Samson!” He didn’t know the Lord had left him. They gouged out his eyes and put him to work grinding grain in prison.", ("Judges",16)),
  C("The last prayer", "At a Philistine festival, blind Samson prayed for strength once more, pushed the pillars, and the temple fell. He killed more in his death than in his life.",
    "His hair had begun to grow back. He prayed, “Sovereign Lord, remember me.” Hebrews lists him among the heroes of faith.", ("Judges",16)),
 ]),
 dict(id="ruth", name="Ruth", role="The loyal foreigner who became great-grandma of a king", art="ruth-naomi",
  facts=["From Moab", "Loyal to Naomi", "Married Boaz"], cards=[
  C("Widowed in Moab", "During a famine, an Israelite family moved to Moab. Both sons married Moabite women — then the father and both sons died.",
    "Naomi was left with two daughters-in-law, Orpah and Ruth, and no way to support them.", ("Ruth",1)),
  C("“Your God, my God”", "Naomi told them to go home. Orpah left. Ruth clung to her: “Where you go I will go… your people will be my people and your God my God.”",
    "Back in Bethlehem, Naomi told the women, “Don’t call me Naomi (pleasant). Call me Mara (bitter).”", ("Ruth",1)),
  C("Gleaning in Boaz’s field", "Ruth gathered leftover grain behind the harvesters. The owner, Boaz — a relative — protected her and gave her extra.",
    "God’s law told farmers to leave the edges of fields for the poor and foreigners. Boaz told his men to drop extra stalks on purpose.", ("Ruth",2)),
  C("At the threshing floor", "Following Naomi’s plan, Ruth lay at Boaz’s feet at night and asked him to be her family redeemer.",
    "A “kinsman-redeemer” could buy back family land and marry a widow to carry on the family name. Boaz was moved and praised her loyalty.", ("Ruth",3)),
  C("A grandson for Naomi", "Boaz married Ruth. Their son Obed was the grandfather of King David.",
    "The women of Bethlehem told Naomi that Ruth was better to her than seven sons. Ruth is one of four women named in Jesus’ family tree in Matthew.", ("Ruth",4)),
 ]),
 dict(id="hannah", name="Hannah", role="The mother whose tearful prayer was answered", art=None,
  facts=["Couldn’t have children", "Prayed at the temple", "Mother of Samuel"], cards=[
  C("Year after year", "Hannah couldn’t have children, and her husband’s other wife taunted her every year at the festival.",
    "Her husband Elkanah loved her: “Don’t I mean more to you than ten sons?”", ("1 Samuel",1)),
  C("The silent prayer", "At the house of God, Hannah prayed so hard her lips moved without sound. The priest Eli thought she was drunk.",
    "She vowed that if God gave her a son, she would give him to the Lord for his whole life. Eli blessed her.", ("1 Samuel",1)),
  C("Keeping her promise", "God gave her a son, Samuel. When he was weaned, she brought him to serve at God’s house — and sang a song of praise.",
    "Every year she made him a little robe and brought it. God gave her three more sons and two daughters. Her song in 1 Samuel 2 echoes in Mary’s Magnificat.", ("1 Samuel",2)),
 ]),
 dict(id="samuel", name="Samuel", role="The boy who heard God’s voice and anointed kings", art=None,
  facts=["Hannah’s son", "“Speak, Lord”", "Anointed Saul and David"], cards=[
  C("“Speak, Lord”", "Young Samuel heard someone call his name at night. The third time, Eli realized it was God: “Say, ‘Speak, Lord, for Your servant is listening.’”",
    "God’s message was hard: judgment on Eli’s corrupt sons. Samuel told Eli the whole truth.", ("1 Samuel",3)),
  C("Prophet and judge", "Samuel grew up and all Israel recognized him as God’s prophet. He led the nation as its last judge.",
    "He traveled a circuit judging Israel and led them to turn from idols.", ("1 Samuel",7)),
  C("“Give us a king”", "The people demanded a king like other nations. God told Samuel to give them one, and Samuel anointed Saul.",
    "God said, “It is not you they have rejected, but they have rejected Me as their king.”", ("1 Samuel",8)),
  C("The heart, not the height", "When Saul failed, God sent Samuel to anoint one of Jesse’s sons. God chose the youngest: David.",
    "Samuel thought the tall oldest son must be the one. God said, “People look at the outward appearance, but the Lord looks at the heart.”", ("1 Samuel",16)),
 ]),
])

cat("kings", "Kings & Queens", "The rulers of Israel and Judah — the good, the bad and the in-between.", "solomon-judgment", [
 dict(id="saul", name="Saul", role="Israel’s first king", art=None,
  facts=["Tall and handsome", "Disobeyed God", "Jealous of David"], cards=[
  C("Looking for donkeys", "Saul was out looking for his father’s lost donkeys when Samuel anointed him king.",
    "He was a head taller than anyone else. At his public choosing, he hid among the baggage.", ("1 Samuel",9)),
  C("A strong start", "Saul rescued the city of Jabesh-gilead from the Ammonites, and the people celebrated him as king.",
    "He won many battles against Israel’s enemies.", ("1 Samuel",11)),
  C("Doing it his way", "Saul offered a sacrifice he wasn’t allowed to and later disobeyed God’s orders in battle. Samuel said, “To obey is better than sacrifice.”",
    "God rejected him as king. An evil spirit tormented him, and young David was brought in to play the harp to calm him.", ("1 Samuel",15)),
  C("Jealous rage", "When women sang that Saul killed thousands and David tens of thousands, Saul became obsessed with killing David.",
    "He threw spears at David and chased him through the wilderness for years.", ("1 Samuel",18)),
  C("How it ended", "Desperate before battle, Saul consulted a medium at Endor. The next day, badly wounded, he fell on his own sword.",
    "Three of his sons, including Jonathan, died the same day on Mount Gilboa. David wrote a lament: “How the mighty have fallen!”", ("1 Samuel",31)),
 ]),
 dict(id="david", name="David", role="Shepherd, giant-killer, king — “a man after God’s own heart”", art="goliath",
  facts=["Youngest of 8 brothers", "Killed Goliath", "Wrote many Psalms"], cards=[
  C("The forgotten son", "Samuel came to anoint a king from Jesse’s sons. David, the youngest, was out with the sheep — nobody called him in.",
    "God passed over all seven older sons. When David came in, God said, “Rise and anoint him; this is the one.” The Spirit of the Lord came on him powerfully from that day.", ("1 Samuel",16)),
  C("The giant", "Teenage David faced 9-foot Goliath with a sling and five stones: “I come against you in the name of the Lord.”",
    "He’d killed lions and bears defending his sheep. He refused Saul’s armor. The stone struck Goliath’s forehead, and David cut off the giant’s head with the giant’s own sword.", ("1 Samuel",17)),
  C("Best friends", "Saul’s son Jonathan loved David like his own soul. He warned David when Saul planned to kill him.",
    "Jonathan gave David his robe, sword and bow — symbolically handing over his right to the throne. They made a covenant of friendship.", ("1 Samuel",20)),
  C("On the run", "For years David hid in caves from Saul. Twice he could have killed Saul and refused: “I won’t harm the Lord’s anointed.”",
    "Hundreds of outcasts gathered around him and became his mighty men. Many psalms come from this time: “The Lord is my rock, my fortress and my deliverer.”", ("1 Samuel",24)),
  C("King in Jerusalem", "At 30 David became king. He captured Jerusalem, made it his capital, and brought the Ark there, dancing with all his might.",
    "God promised David that his throne would be established forever — the promise fulfilled in Jesus, the Son of David.", ("2 Samuel",7)),
  C("Bathsheba", "David slept with Bathsheba, another man’s wife, then arranged for her husband Uriah to die in battle.",
    "The prophet Nathan told David a story about a rich man stealing a poor man’s only lamb. David was outraged — and Nathan said, “You are the man!” David confessed. Psalm 51 is his prayer: “Create in me a clean heart, O God.”", ("2 Samuel",12)),
  C("Family pain", "Violence followed David’s house. His son Absalom rebelled, drove him from Jerusalem, and died in battle.",
    "David wept, “O my son Absalom! If only I had died instead of you!”", ("2 Samuel",18)),
  C("His legacy", "David reigned 40 years. He wrote about half of the Psalms, including “The Lord is my shepherd.”",
    "He passed the throne to Solomon and gathered materials for the Temple. Jesus was born in Bethlehem, the city of David, and called “Son of David.”", ("Psalms",22)),
 ]),
 dict(id="solomon", name="Solomon", role="The wisest king — who lost his way", art="solomon-judgment",
  facts=["Son of David", "Built the Temple", "Wrote Proverbs"], cards=[
  C("Ask for anything", "God appeared to young King Solomon in a dream: “Ask for whatever you want.” He asked for wisdom to govern well.",
    "God was pleased and gave him wisdom — plus riches and honor he didn’t ask for.", ("1 Kings",3)),
  C("The two mothers", "Two women claimed the same baby. Solomon ordered it cut in half. The real mother begged him to spare it — revealing the truth.",
    "All Israel was in awe, seeing he had wisdom from God.", ("1 Kings",3)),
  C("The Temple", "Solomon built a magnificent Temple in Jerusalem over seven years. God’s glory filled it like a cloud.",
    "At the dedication he prayed, “The heavens, even the highest heavens, cannot contain You. How much less this temple I have built!”", ("1 Kings",8)),
  C("The Queen of Sheba", "Solomon’s fame drew the Queen of Sheba, who tested him with hard questions. He answered them all.",
    "He wrote 3,000 proverbs and 1,005 songs. Proverbs, Ecclesiastes and the Song of Songs are linked with him.", ("1 Kings",10)),
  C("How it ended", "Solomon married 700 wives and had 300 concubines. In old age they turned his heart to other gods.",
    "God said the kingdom would be torn from his family — though not in his lifetime. After he died, the ten northern tribes split away.", ("1 Kings",11)),
 ]),
 dict(id="esther", name="Esther", role="The queen who risked her life to save her people", art="esther",
  facts=["Jewish orphan", "Became queen of Persia", "“For such a time as this”"], cards=[
  C("An orphan in Persia", "Esther, also called Hadassah, was a Jewish orphan raised by her cousin Mordecai in the Persian capital.",
    "Her people had been exiled there generations earlier.", ("Esther",2)),
  C("Chosen queen", "King Xerxes deposed Queen Vashti and searched for a new queen. He chose Esther, who kept her Jewish identity secret.",
    "Mordecai also uncovered a plot to assassinate the king, which was recorded but forgotten.", ("Esther",2)),
  C("Haman’s plot", "Haman, the king’s top official, raged when Mordecai wouldn’t bow, and got the king to order every Jew killed on a set day.",
    "He cast lots (pur) to choose the date.", ("Esther",3)),
  C("“For such a time as this”", "Mordecai urged Esther to go to the king. Approaching uninvited could mean death. She fasted three days: “If I perish, I perish.”",
    "Mordecai said, “Who knows but that you have come to your royal position for such a time as this?”", ("Esther",4)),
  C("The banquets", "The king spared her. At a second banquet she exposed Haman. He was hanged on the gallows he built for Mordecai.",
    "The night between, the king couldn’t sleep, read the records, and honored Mordecai — led through the city by Haman himself. The Jews were allowed to defend themselves, and the feast of Purim still celebrates it.", ("Esther",7)),
 ]),
 dict(id="hezekiah", name="Hezekiah", role="The king who prayed when an army surrounded him", art="sennacherib",
  facts=["King of Judah", "Tore down idols", "God added 15 years to his life"], cards=[
  C("Cleaning house", "Hezekiah became king at 25. He reopened the Temple, destroyed idols, and celebrated Passover again.",
    "He even smashed Moses’ bronze snake, which people had started worshiping. “There was no one like him among all the kings of Judah.”", ("2 Kings",18)),
  C("Under siege", "The Assyrian army surrounded Jerusalem and mocked God. Hezekiah spread the threatening letter before the Lord and prayed.",
    "He also dug a tunnel to bring water into the city — Hezekiah’s Tunnel still exists today.", ("2 Kings",19)),
  C("One night", "That night the angel of the Lord struck 185,000 Assyrian soldiers. King Sennacherib went home and was later killed by his sons.",
    "Assyrian records boast of trapping Hezekiah “like a bird in a cage” — but never claim to capture Jerusalem.", ("2 Kings",19)),
  C("15 more years", "Hezekiah got deathly sick and wept before God. God added 15 years to his life and made a shadow go backward as a sign.",
    "Afterward he foolishly showed Babylonian envoys all his treasures, and Isaiah warned that Babylon would one day carry it all away.", ("2 Kings",20)),
 ]),
 dict(id="josiah", name="Josiah", role="The boy king who rediscovered God’s Word", art=None,
  facts=["King at age 8", "Found the lost Book of the Law", "Led a revival"], cards=[
  C("King at eight", "Josiah became king after his father was assassinated. At 16 he began to seek God.",
    "His grandfather Manasseh was the most wicked king in Judah’s history.", ("2 Kings",22)),
  C("The lost book", "Repairing the Temple, workers found the Book of the Law. When it was read, Josiah tore his robes.",
    "He realized how far the nation had strayed. The prophetess Huldah confirmed judgment would come, but not in his lifetime because his heart was humble.", ("2 Kings",22)),
  C("Revival", "Josiah read the law to all the people, destroyed idols everywhere, and held the greatest Passover since the judges.",
    "He died at 39 in battle against Pharaoh Neco. Jeremiah wrote laments for him.", ("2 Kings",23)),
 ]),
])
